            </div>
            <div className="hidden md:flex items-center gap-8">
              <a href="#features" className="text-sm font-medium hover:text-navy-900 dark:hover:text-white transition-colors">{t.nav.features}</a>
              <button onClick={scrollToDemo} className="text-sm font-medium hover:text-navy-900 dark:hover:text-white transition-colors">{t.nav.demo}</button>
              <a href="#pricing" className="text-sm font-medium hover:text-navy-900 dark:hover:text-white transition-colors">{t.nav.pricing}</a>
            </div>
            <div className="flex items-center gap-4">
               {/* Global Language Switcher (Mini) */}
               <div className="hidden sm:flex items-center gap-2 mr-2">
                   <button onClick={() => setLanguage('English')} className={`text-xs font-bold px-2 py-1 rounded ${language === 'English' ? 'bg-slate-100 dark:bg-slate-800' : 'text-slate-400'}`}>EN</button>
                   <button onClick={() => setLanguage('Hindi')} className={`text-xs font-bold px-2 py-1 rounded ${language === 'Hindi' ? 'bg-slate-100 dark:bg-slate-800' : 'text-slate-400'}`}>HI</button>
                   <button onClick={() => setLanguage('Bengali')} className={`text-xs font-bold px-2 py-1 rounded ${language === 'Bengali' ? 'bg-slate-100 dark:bg-slate-800' : 'text-slate-400'}`}>BN</button>
               </div>

               <button 
                onClick={toggleTheme}
                className="p-2 rounded-full text-slate-500 hover:bg-slate-100 dark:text-slate-400 dark:hover:bg-slate-800 transition-colors"
                aria-label="Toggle Dark Mode"
               >
                 {isDarkMode ? <Sun className="w-5 h-5" /> : <Moon className="w-5 h-5" />}
               </button>

               {currentUser ? (
